#!/usr/bin/env python3
"""
Correcao tripla:

1) Crash ao clicar no editor de capa (lapis):
   IllegalArgumentException "column '_data' does not exist" -
   ImageLoader.getLocalPathFromUri() (herdado do AOSP original, feito so
   para Uris do MediaStore) estava sendo chamado tambem com Uris de
   FileProvider (a capa temporaria salva em cache pra edicao, ver
   MoviePlayer.onEditCover()), cujo provider nao tem coluna _data -
   derrubava o app inteiro. Agora so devolve null nesse caso (quem chama
   ja trata path==null sem problema).

2) Botao de editar capa (lapis) sobrepondo o botao de play:
   Movido da area inferior (que disputava espaco com Play/Anterior/
   Proxima em telas menores/paisagem) para o canto SUPERIOR direito da
   tela, espaco proprio, sem sair das dimensoes da tela.

3) Botoes de Repetir Todas/Repetir Uma nao aparecendo na notificacao
   expandida (Samsung One UI, Android 13+):
   causa raiz real - o app usava a MediaSession da API framework
   (android.media.session), que NUNCA teve suporte a repeat mode. O
   template de notificacao de midia redesenhado do Android 13+ so
   reconhece/desenha um controle de repetir quando a sessao publica
   PlaybackStateCompat.ACTION_SET_REPEAT_MODE + chama
   MediaSessionCompat.setRepeatMode() - API que so existe na biblioteca
   de compatibilidade androidx.media, nao na API framework. Migrado
   MediaSession/PlaybackState/MediaMetadata (framework) para
   MediaSessionCompat/PlaybackStateCompat/MediaMetadataCompat +
   NotificationCompat (androidx.media / androidx.core), mantendo os
   mesmos 5 botoes customizados de antes (que continuam funcionando
   igual) e ADICIONANDO a publicacao do repeat mode nativo. Nova
   dependencia androidx.media:media:1.7.0 adicionada ao build.gradle.kts.

Rode este script de dentro de ~/Galeria3D (raiz do repo clonado).
Idempotente: pode rodar 2x sem quebrar nada.
Cada arquivo tocado ganha um .bak antes de ser sobrescrito.

IMPORTANTE: como foi adicionada uma dependencia nova (androidx.media),
o Gradle vai precisar baixar ela na primeira compilacao depois de rodar
este script - certifique-se de ter internet disponivel nesse build.
"""

import base64
import io
import os
import shutil
import sys
import tarfile

FILES = {
    "app/src/main/java/com/android/gallery3d/app/MovieControllerOverlay.java": "MovieControllerOverlay.java",
    "app/src/main/java/com/android/gallery3d/app/MusicPlaybackService.java": "MusicPlaybackService.java",
    "app/src/main/java/com/android/gallery3d/filtershow/cache/ImageLoader.java": "ImageLoader.java",
    "app/build.gradle.kts": "build.gradle.kts",
}

PAYLOAD_B64 = ""


def load_payload():
    raw = base64.b64decode(PAYLOAD_B64)
    return tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz")


def already_applied():
    path = "app/src/main/java/com/android/gallery3d/app/MusicPlaybackService.java"
    if not os.path.isfile(path):
        return False
    with open(path, "r", encoding="utf-8") as f:
        return "MediaSessionCompat" in f.read()


def main():
    if not os.path.isdir("app/src/main/java/com/android/gallery3d"):
        print("ERRO: nao encontrei app/src/main/java/com/android/gallery3d")
        print("Rode este script de dentro da pasta raiz do repo (~/Galeria3D).")
        sys.exit(1)

    if already_applied():
        print("Correcao ja aplicada anteriormente (MusicPlaybackService.java ja usa")
        print("MediaSessionCompat) - nada a fazer (script e idempotente).")
        sys.exit(0)

    tar = load_payload()
    members = {m.name.lstrip("./"): m for m in tar.getmembers()}

    for repo_path, payload_name in FILES.items():
        if payload_name not in members:
            print(f"ERRO interno: payload nao contem {payload_name}")
            sys.exit(1)

    backups = []
    try:
        for repo_path, payload_name in FILES.items():
            new_content = tar.extractfile(members[payload_name]).read()

            if os.path.isfile(repo_path):
                backup_path = repo_path + ".bak"
                shutil.copyfile(repo_path, backup_path)
                backups.append(backup_path)
                print(f"Backup criado: {backup_path}")
            else:
                os.makedirs(os.path.dirname(repo_path), exist_ok=True)

            with open(repo_path, "wb") as f:
                f.write(new_content)
            print(f"Atualizado: {repo_path}")

    except Exception as e:
        print(f"ERRO durante a aplicacao: {e}")
        print("Arquivos ja copiados tem backup .bak ao lado, revise manualmente se necessario.")
        sys.exit(1)

    print()
    print("Correcao aplicada com sucesso.")
    print()
    print("O que foi feito:")
    print("- ImageLoader.java: nao crasha mais ao editar a capa (Uri de")
    print("  FileProvider sem coluna _data)")
    print("- MovieControllerOverlay.java: botao de editar capa movido para")
    print("  o canto superior direito, espaco proprio")
    print("- MusicPlaybackService.java: MediaSession migrada para")
    print("  MediaSessionCompat (androidx.media), com suporte real a")
    print("  repeat mode nativo - deve resolver os botoes de repeat")
    print("  sumindo no expandido da notificacao no One UI")
    print("- build.gradle.kts: nova dependencia androidx.media:media:1.7.0")
    print()
    print("Proximo passo: rode ./gradlew assembleDebug (com internet")
    print("disponivel, para baixar a dependencia nova) e teste:")
    print("1. Editar capa (nao deve mais crashar)")
    print("2. Posicao do botao de editar capa (canto superior direito)")
    print("3. Notificacao expandida (botoes de repetir nas pontas)")


if __name__ == "__main__":
    main()
